"use client"

import * as React from "react"
import {
  DndContext,
  KeyboardSensor,
  PointerSensor,
  closestCenter,
  useSensor,
  useSensors,
  type DragEndEvent,
} from "@dnd-kit/core"
import {
  SortableContext,
  rectSortingStrategy,
  sortableKeyboardCoordinates,
  useSortable,
  verticalListSortingStrategy,
} from "@dnd-kit/sortable"
import { CSS } from "@dnd-kit/utilities"
import { GripVertical, LayoutGrid, List, Pencil, Search } from "lucide-react"
import { toast } from "sonner"

import { cn } from "@/lib/utils"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Switch } from "@/components/ui/switch"
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { useOptimisticList } from "@/registry/retana/hooks/use-optimistic-list"
import { EmptyState } from "@/registry/retana/ui/entity-form"
import { Thumb } from "@/registry/retana/ui/sortable-list"

export type BoardItem = {
  id: string
  title: string
  categoryId: string | null
  categoryTitle?: string | null
  imageUrl?: string | null
  videoUrl?: string | null
  showOnHomepage: boolean
}

export type BoardCategory = {
  id: string
  title: string
}

export type SortableBoardProps = {
  items: readonly BoardItem[]
  categories: readonly BoardCategory[]
  onReorder: (ids: readonly string[]) => Promise<void> | void
  onToggleHomepage: (id: string, show: boolean) => Promise<void> | void
  onEdit?: (id: string) => void
  view?: "list" | "grid"
  onViewChange?: (view: "list" | "grid") => void
  query?: string
  onQueryChange?: (query: string) => void
  filter?: string
  onFilterChange?: (filter: string) => void
  addButton?: React.ReactNode
  className?: string
  homepageLabel?: string
  searchLabel?: string
  editLabel?: string
  emptyTitle?: string
}

export function SortableBoard({
  items,
  categories,
  onReorder,
  onToggleHomepage,
  onEdit,
  view: viewProp,
  onViewChange,
  query: queryProp,
  onQueryChange,
  filter: filterProp,
  onFilterChange,
  addButton,
  className,
  homepageLabel = "Homepage",
  searchLabel = "Search",
  editLabel = "Edit",
  emptyTitle = "No matches",
}: SortableBoardProps) {
  const [viewState, setViewState] = React.useState<"list" | "grid">("list")
  const [queryState, setQueryState] = React.useState("")
  const [filterState, setFilterState] = React.useState("all")
  const [home, setHome] = React.useState<Record<string, boolean>>({})
  const view = viewProp ?? viewState
  const query = queryProp ?? queryState
  const filter = filterProp ?? filterState

  const notify = React.useMemo(
    () => ({
      success: (message: string) => toast.success(message),
      error: (message: string) => toast.error(message),
    }),
    [],
  )
  const list = useOptimisticList({ items, onReorder, notify, savedMessage: "Order saved" })

  function isHome(item: BoardItem) {
    return home[item.id] ?? item.showOnHomepage
  }

  const q = query.trim().toLowerCase()
  const visible = list.items.filter((item) => {
    if (filter === "home" && !isHome(item)) return false
    if (filter === "none" && item.categoryId) return false
    if (filter.startsWith("cat:") && item.categoryId !== filter.slice(4)) return false
    if (!q) return true
    return (
      item.title.toLowerCase().includes(q) ||
      (item.categoryTitle ?? "").toLowerCase().includes(q)
    )
  })
  const visibleIds = visible.map((item) => item.id)

  const chips = [
    { key: "all", label: "All", n: items.length },
    { key: "home", label: homepageLabel, n: list.items.filter(isHome).length },
    ...categories.map((category) => ({
      key: `cat:${category.id}`,
      label: category.title,
      n: items.filter((item) => item.categoryId === category.id).length,
    })),
  ]
  const uncategorized = items.filter((item) => !item.categoryId).length
  if (uncategorized) chips.push({ key: "none", label: "No category", n: uncategorized })

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates }),
  )

  function place(id: string | number) {
    return visibleIds.indexOf(String(id)) + 1
  }

  function onDragEnd(event: DragEndEvent) {
    if (!event.over || event.active.id === event.over.id) return
    list.moveVisible(visibleIds, String(event.active.id), String(event.over.id))
  }

  async function toggle(item: BoardItem) {
    const next = !isHome(item)
    setHome((current) => ({ ...current, [item.id]: next }))
    try {
      await onToggleHomepage(item.id, next)
    } catch (error) {
      setHome((current) => ({ ...current, [item.id]: !next }))
      toast.error(error instanceof Error && error.message ? error.message : "Could not update")
    }
  }

  function setView(next: "list" | "grid") {
    setViewState(next)
    onViewChange?.(next)
  }
  function setQuery(next: string) {
    setQueryState(next)
    onQueryChange?.(next)
  }
  function setFilter(next: string) {
    setFilterState(next)
    onFilterChange?.(next)
  }

  return (
    <div className={cn("flex flex-col gap-3", className)}>
      <div className="flex flex-col gap-3 lg:flex-row lg:items-center">
        <Tabs value={filter} onValueChange={setFilter} className="min-w-0">
          <TabsList className="h-auto flex-wrap">
            {chips.map((chip) => (
              <TabsTrigger key={chip.key} value={chip.key}>
                {chip.label}
                <Badge variant="secondary" className="ml-1 tabular-nums">
                  {chip.n}
                </Badge>
              </TabsTrigger>
            ))}
          </TabsList>
        </Tabs>
        <div className="flex flex-1 items-center gap-2 lg:justify-end">
          <div className="relative min-w-40 flex-1 lg:max-w-xs">
            <Search className="pointer-events-none absolute top-1/2 left-2 size-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              placeholder={searchLabel}
              aria-label={searchLabel}
              className="pl-8"
            />
          </div>
          <div className="flex rounded-lg bg-muted p-0.5" role="group" aria-label="View">
            <Button
              type="button"
              size="sm"
              variant={view === "list" ? "secondary" : "ghost"}
              aria-pressed={view === "list"}
              onClick={() => setView("list")}
            >
              <List />
              List
            </Button>
            <Button
              type="button"
              size="sm"
              variant={view === "grid" ? "secondary" : "ghost"}
              aria-pressed={view === "grid"}
              onClick={() => setView("grid")}
            >
              <LayoutGrid />
              Grid
            </Button>
          </div>
          {addButton}
        </div>
      </div>
      <p className="text-xs text-muted-foreground">
        {filter !== "all" || q
          ? "Reordering swaps the projects on screen. The rest stay put."
          : "Drag the handle. This order is the order on the site."}
      </p>
      {visible.length === 0 ? (
        <EmptyState title={emptyTitle} />
      ) : (
        <DndContext
          sensors={sensors}
          collisionDetection={closestCenter}
          onDragEnd={onDragEnd}
          accessibility={{
            screenReaderInstructions: {
              draggable: "Press Space, then arrow keys, then Space to drop. Escape cancels.",
            },
            announcements: {
              onDragStart: ({ active }) => `Picked up, place ${place(active.id)} of ${visibleIds.length}.`,
              onDragOver: ({ over }) => (over ? `Over place ${place(over.id)}.` : ""),
              onDragEnd: ({ over }) => (over ? `Dropped at place ${place(over.id)}.` : "Dropped."),
              onDragCancel: () => "Cancelled.",
            },
          }}
        >
          <SortableContext
            items={visibleIds}
            strategy={view === "grid" ? rectSortingStrategy : verticalListSortingStrategy}
          >
            <ol
              className={cn(
                view === "grid"
                  ? "grid gap-3 sm:grid-cols-2 xl:grid-cols-3"
                  : "flex flex-col gap-2",
              )}
            >
              {visible.map((item, index) => (
                <BoardCard
                  key={item.id}
                  item={item}
                  index={index}
                  view={view}
                  home={isHome(item)}
                  homepageLabel={homepageLabel}
                  editLabel={editLabel}
                  onEdit={onEdit}
                  onToggle={() => void toggle(item)}
                />
              ))}
            </ol>
          </SortableContext>
        </DndContext>
      )}
    </div>
  )
}

function BoardCard({
  item,
  index,
  view,
  home,
  homepageLabel,
  editLabel,
  onEdit,
  onToggle,
}: {
  item: BoardItem
  index: number
  view: "list" | "grid"
  home: boolean
  homepageLabel: string
  editLabel: string
  onEdit?: (id: string) => void
  onToggle: () => void
}) {
  const { attributes, listeners, setNodeRef, setActivatorNodeRef, transform, transition, isDragging } =
    useSortable({ id: item.id })
  const style = { transform: CSS.Transform.toString(transform), transition }
  const thumb = item.imageUrl || item.videoUrl

  return (
    <li
      ref={setNodeRef}
      style={style}
      className={cn(
        "flex gap-3 rounded-xl bg-card p-2 ring-1 ring-foreground/10",
        view === "grid" ? "flex-col" : "items-center",
        isDragging && "opacity-70",
      )}
    >
      <div className={cn("flex items-center gap-2", view === "grid" && "w-full")}>
        <Button
          type="button"
          ref={setActivatorNodeRef}
          variant="ghost"
          size="icon-sm"
          className="cursor-grab touch-none"
          aria-label={`Reorder ${item.title}`}
          {...attributes}
          {...listeners}
        >
          <GripVertical />
        </Button>
        <span className="text-xs text-muted-foreground tabular-nums">{index + 1}</span>
        {view === "list" ? <Thumb url={thumb} alt={item.title} /> : null}
        {view === "list" ? (
          <div className="min-w-0 flex-1">
            <p className="truncate text-sm font-medium">{item.title}</p>
            <p className="truncate text-xs text-muted-foreground">{item.categoryTitle || "No category"}</p>
          </div>
        ) : null}
      </div>
      {view === "grid" ? (
        <div className="aspect-video overflow-hidden rounded-lg bg-muted">
          {thumb ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img src={thumb} alt="" className="size-full object-cover" />
          ) : (
            <div className="grid size-full place-items-center text-sm text-muted-foreground">
              {item.title.slice(0, 1)}
            </div>
          )}
        </div>
      ) : null}
      {view === "grid" ? (
        <div>
          <p className="truncate text-sm font-medium">{item.title}</p>
          <p className="truncate text-xs text-muted-foreground">{item.categoryTitle || "No category"}</p>
        </div>
      ) : null}
      <div className={cn("flex items-center gap-2", view === "list" && "ml-auto")}>
        <label className="flex items-center gap-2 text-xs text-muted-foreground">
          <Switch checked={home} onCheckedChange={onToggle} aria-label={`${homepageLabel}: ${item.title}`} />
          <span className="hidden md:inline">{homepageLabel}</span>
        </label>
        {onEdit ? (
          <Button type="button" variant="outline" size="sm" onClick={() => onEdit(item.id)}>
            <Pencil />
            {editLabel}
          </Button>
        ) : null}
      </div>
    </li>
  )
}

"use client"

import * as React from "react"
import {
  DndContext,
  KeyboardSensor,
  PointerSensor,
  closestCenter,
  useSensor,
  useSensors,
  type DragEndEvent,
} from "@dnd-kit/core"
import {
  SortableContext,
  sortableKeyboardCoordinates,
  useSortable,
  verticalListSortingStrategy,
} from "@dnd-kit/sortable"
import { CSS } from "@dnd-kit/utilities"
import {
  ArrowDown,
  ArrowDownToLine,
  ArrowUp,
  ArrowUpToLine,
  GripVertical,
  Pencil,
} from "lucide-react"
import { toast } from "sonner"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { destinationIndex } from "@/registry/retana/lib/reorder"
import { useOptimisticList } from "@/registry/retana/hooks/use-optimistic-list"
import { EmptyState } from "@/registry/retana/ui/entity-form"

export type SortableListItem = {
  id: string
  title: string
  meta?: string
  thumbnailUrl?: string | null
  thumbnailAlt?: string
}

export type SortableListProps = {
  items: readonly SortableListItem[]
  onReorder: (ids: readonly string[]) => Promise<void> | void
  onEdit?: (id: string) => void
  /** Visible subset. Hidden ids keep their places when this list is reordered. */
  visibleIds?: readonly string[]
  label?: string
  editLabel?: string
  emptyTitle?: string
  emptyDescription?: string
  className?: string
  savedMessage?: string
  errorMessage?: string
}

function isVideo(url: string) {
  return /\.(mp4|webm|mov)($|\?)/i.test(url)
}

export function SortableList({
  items,
  onReorder,
  onEdit,
  visibleIds,
  label = "rows",
  editLabel = "Edit",
  emptyTitle = "Nothing here",
  emptyDescription = "Add an item to start.",
  className,
  savedMessage = "Order saved",
  errorMessage = "Could not save the order",
}: SortableListProps) {
  const notify = React.useMemo(
    () => ({
      success: (message: string) => toast.success(message),
      error: (message: string) => toast.error(message),
    }),
    [],
  )
  const list = useOptimisticList({
    items,
    onReorder,
    notify,
    savedMessage,
    errorMessage,
  })
  const shown = visibleIds
    ? list.items.filter((item) => visibleIds.includes(item.id))
    : list.items
  const shownIds = shown.map((item) => item.id)

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates }),
  )

  function place(id: string | number) {
    return shownIds.indexOf(String(id)) + 1
  }

  function onDragEnd(event: DragEndEvent) {
    if (!event.over || event.active.id === event.over.id) return
    list.moveVisible(shownIds, String(event.active.id), String(event.over.id))
  }

  function move(id: string, target: "up" | "down" | "top" | "bottom") {
    const index = shownIds.indexOf(id)
    if (index < 0) return
    const to = destinationIndex(index, shownIds.length, target)
    const overId = shownIds[to]
    if (!overId) return
    list.moveVisible(shownIds, id, overId)
  }

  if (shown.length === 0) {
    return <EmptyState title={emptyTitle} description={emptyDescription} className={className} />
  }

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={closestCenter}
      onDragEnd={onDragEnd}
      accessibility={{
        screenReaderInstructions: {
          draggable:
            "To reorder, press Space. Use the arrow keys to move, Space to drop, Escape to cancel.",
        },
        announcements: {
          onDragStart: ({ active }) =>
            `Picked up, place ${place(active.id)} of ${shownIds.length} ${label}.`,
          onDragOver: ({ over }) => (over ? `Over place ${place(over.id)}.` : "Not over a place."),
          onDragEnd: ({ over }) => (over ? `Dropped at place ${place(over.id)}.` : "Dropped."),
          onDragCancel: () => "Cancelled.",
        },
      }}
    >
      <SortableContext items={shownIds} strategy={verticalListSortingStrategy}>
        <ol className={cn("flex flex-col gap-2", className)}>
          {shown.map((item) => (
            <SortableRow
              key={item.id}
              item={item}
              index={shownIds.indexOf(item.id)}
              count={shownIds.length}
              editLabel={editLabel}
              onEdit={onEdit}
              onMove={move}
            />
          ))}
        </ol>
      </SortableContext>
    </DndContext>
  )
}

function SortableRow({
  item,
  index,
  count,
  editLabel,
  onEdit,
  onMove,
}: {
  item: SortableListItem
  index: number
  count: number
  editLabel: string
  onEdit?: (id: string) => void
  onMove: (id: string, target: "up" | "down" | "top" | "bottom") => void
}) {
  const { attributes, listeners, setNodeRef, setActivatorNodeRef, transform, transition, isDragging } =
    useSortable({ id: item.id })
  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  }

  return (
    <li
      ref={setNodeRef}
      style={style}
      className={cn(
        "flex items-center gap-2 rounded-xl bg-card px-2 py-2 ring-1 ring-foreground/10",
        isDragging && "opacity-70",
      )}
    >
      <Button
        type="button"
        ref={setActivatorNodeRef}
        variant="ghost"
        size="icon-sm"
        className="cursor-grab touch-none active:cursor-grabbing motion-reduce:transition-none"
        aria-label={`Reorder ${item.title}`}
        {...attributes}
        {...listeners}
      >
        <GripVertical />
      </Button>
      <span className="w-6 text-center text-xs text-muted-foreground tabular-nums">{index + 1}</span>
      <Thumb url={item.thumbnailUrl} alt={item.thumbnailAlt ?? ""} />
      <div className="min-w-0 flex-1">
        <p className="truncate text-sm font-medium">{item.title}</p>
        {item.meta ? <p className="truncate text-xs text-muted-foreground">{item.meta}</p> : null}
      </div>
      <div className="hidden items-center gap-0.5 sm:flex">
        <MoveButton label={`Move ${item.title} to the top`} disabled={index <= 0} onClick={() => onMove(item.id, "top")}>
          <ArrowUpToLine />
        </MoveButton>
        <MoveButton label={`Move ${item.title} up`} disabled={index <= 0} onClick={() => onMove(item.id, "up")}>
          <ArrowUp />
        </MoveButton>
        <MoveButton label={`Move ${item.title} down`} disabled={index >= count - 1} onClick={() => onMove(item.id, "down")}>
          <ArrowDown />
        </MoveButton>
        <MoveButton label={`Move ${item.title} to the bottom`} disabled={index >= count - 1} onClick={() => onMove(item.id, "bottom")}>
          <ArrowDownToLine />
        </MoveButton>
      </div>
      {onEdit ? (
        <Button type="button" variant="outline" size="sm" onClick={() => onEdit(item.id)}>
          <Pencil />
          {editLabel}
        </Button>
      ) : null}
    </li>
  )
}

function MoveButton({
  label,
  disabled,
  onClick,
  children,
}: {
  label: string
  disabled: boolean
  onClick: () => void
  children: React.ReactNode
}) {
  return (
    <Button type="button" variant="ghost" size="icon-sm" aria-label={label} title={label} disabled={disabled} onClick={onClick}>
      {children}
    </Button>
  )
}

export function Thumb({ url, alt }: { url?: string | null; alt: string }) {
  if (!url) {
    return (
      <span className="grid size-10 shrink-0 place-items-center rounded-md bg-muted text-xs font-medium text-muted-foreground">
        {alt.slice(0, 1).toUpperCase() || "·"}
      </span>
    )
  }
  if (isVideo(url)) {
    return <video className="size-10 shrink-0 rounded-md bg-muted object-cover" src={url} muted playsInline />
  }
  // eslint-disable-next-line @next/next/no-img-element
  return <img className="size-10 shrink-0 rounded-md bg-muted object-cover" src={url} alt={alt} />
}

"use client"

import * as React from "react"
import { ChevronDown, Inbox } from "lucide-react"

import { cn } from "@/lib/utils"
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { Button } from "@/components/ui/button"
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet"

export type EntityFormProps = {
  open: boolean
  onOpenChange: (open: boolean) => void
  title: string
  description?: string
  presentation?: "dialog" | "sheet"
  onSubmit: (formData: FormData) => Promise<void> | void
  onDelete?: () => Promise<void> | void
  submitLabel?: string
  cancelLabel?: string
  deleteLabel?: string
  busy?: boolean
  children?: React.ReactNode
  className?: string
}

/**
 * Create or edit one record in a dialog or a sheet.
 *
 * Position is not part of the form. The parent should pass the existing
 * `position` through `keepPosition` so a save does not send the row to the end.
 * While `busy` is true (an upload, for example) submit stays disabled.
 */
export function EntityForm({
  open,
  onOpenChange,
  title,
  description,
  presentation = "dialog",
  onSubmit,
  onDelete,
  submitLabel = "Save",
  cancelLabel = "Cancel",
  deleteLabel = "Delete",
  busy = false,
  children,
  className,
}: EntityFormProps) {
  const [pending, setPending] = React.useState(false)
  const [confirmOpen, setConfirmOpen] = React.useState(false)
  const locked = busy || pending

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault()
    if (locked) return
    const formData = new FormData(event.currentTarget)
    setPending(true)
    try {
      await onSubmit(formData)
      onOpenChange(false)
    } finally {
      setPending(false)
    }
  }

  const form = (
    <form className="flex min-h-0 flex-1 flex-col gap-4" onSubmit={handleSubmit}>
      <div className={cn("flex flex-col gap-3", className)}>{children}</div>
      <div className="mt-auto flex flex-wrap items-center gap-2">
        {onDelete ? (
          <Button type="button" variant="destructive" onClick={() => setConfirmOpen(true)} disabled={locked}>
            {deleteLabel}
          </Button>
        ) : null}
        <div className="ml-auto flex gap-2">
          <Button type="button" variant="outline" onClick={() => onOpenChange(false)} disabled={locked}>
            {cancelLabel}
          </Button>
          <Button type="submit" disabled={locked}>
            {pending ? "Saving…" : submitLabel}
          </Button>
        </div>
      </div>
    </form>
  )

  return (
    <>
      {presentation === "sheet" ? (
        <Sheet open={open} onOpenChange={onOpenChange}>
          <SheetContent className="flex w-full flex-col sm:max-w-md" side="right">
            <SheetHeader>
              <SheetTitle>{title}</SheetTitle>
              {description ? <SheetDescription>{description}</SheetDescription> : null}
            </SheetHeader>
            {form}
            <SheetFooter className="hidden" />
          </SheetContent>
        </Sheet>
      ) : (
        <Dialog open={open} onOpenChange={onOpenChange}>
          <DialogContent className="flex max-h-[85vh] flex-col sm:max-w-lg">
            <DialogHeader>
              <DialogTitle>{title}</DialogTitle>
              {description ? <DialogDescription>{description}</DialogDescription> : null}
            </DialogHeader>
            <div className="min-h-0 overflow-y-auto">{form}</div>
            <DialogFooter className="hidden" />
          </DialogContent>
        </Dialog>
      )}
      {onDelete ? (
        <ConfirmDelete
          open={confirmOpen}
          onOpenChange={setConfirmOpen}
          title={deleteLabel}
          description={description ?? title}
          confirmLabel={deleteLabel}
          onConfirm={async () => {
            await onDelete()
            setConfirmOpen(false)
            onOpenChange(false)
          }}
        />
      ) : null}
    </>
  )
}

export type ConfirmDeleteProps = {
  open: boolean
  onOpenChange: (open: boolean) => void
  title?: string
  description?: string
  confirmLabel?: string
  cancelLabel?: string
  onConfirm: () => Promise<void> | void
